import abc

# Define the abstract base class for sorting algorithms.
# This serves as our template, establishing the core operational flow.
class SortAlgorithm(abc.ABC):
    @abc.abstractmethod
    def sort(self, data):
        """
        The template method. Defines the skeleton of the sorting algorithm.
        Subclasses will implement the specific logic for comparison and swapping.
        """
        pass

    @abc.abstractmethod
    def compare(self, a, b):
        """
        Abstract method for element comparison.
        Subclasses must define the criteria for ordering.
        """
        pass

    @abc.abstractmethod
    def swap(self, data, i, j):
        """
        Abstract method for element swapping.
        Subclasses will implement the actual data movement.
        """
        pass

# Concrete implementation for Bubble Sort.
class BubbleSort(SortAlgorithm):
    def sort(self, data):
        n = len(data)
        for i in range(n):
            for j in range(0, n - i - 1):
                # Execute the comparison logic defined by the subclass.
                if self.compare(data[j], data[j + 1]):
                    # If the comparison returns true, initiate the swap protocol.
                    self.swap(data, j, j + 1)
        return data

    def compare(self, a, b):
        # Bubble Sort typically sorts in ascending order.
        return a > b

    def swap(self, data, i, j):
        data[i], data[j] = data[j], data[i]

# Concrete implementation for Selection Sort.
class SelectionSort(SortAlgorithm):
    def sort(self, data):
        n = len(data)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                # Utilize the comparison method to identify the minimum element.
                if self.compare(data[j], data[min_idx]):
                    min_idx = j
            # Execute the swap operation to place the minimum element in its correct position.
            if min_idx != i:
                self.swap(data, i, min_idx)
        return data

    def compare(self, a, b):
        # Selection Sort also typically sorts in ascending order.
        return a < b

    def swap(self, data, i, j):
        data[i], data[j] = data[j], data[i]

# Test harness to validate the implementation.
